using YoWidgets.Core;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

int total=0, failures=0;
async Task Test(string name,Func<Task> run){total++;try{await run();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Check(bool ok,string message="Assertion failed"){if(!ok)throw new Exception(message);}
async Task Reject(Func<Task> run){try{await run();}catch(Exception e) when(e is InvalidDataException or OperationCanceledException or IOException or ArgumentException){return;}throw new Exception("Invalid operation was accepted");}
string root=Path.Combine(Path.GetTempPath(),"YoPlatform-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
var options=CatalogJson.Options;
byte[] Zip(string path,string value){using var m=new MemoryStream();using(var z=new ZipArchive(m,ZipArchiveMode.Create,true)){var e=z.CreateEntry(path);using var s=new StreamWriter(e.Open());s.Write(value);}return m.ToArray();}
var payloads=new Dictionary<string,byte[]>();
ContentPackage Package(string id,string path,string data,string[]? dependencies=null){var bytes=Zip(path,data);payloads[id]=bytes;return new(){Id=id,Version="1.0.0",Url="https://catalog.example/"+id+".zip",Sha256=Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(),Bytes=bytes.Length,Dependencies=dependencies??[]};}
var style=Package("style.glass","style.json","""{"id":"glass","blur":2,"interactionBlur":2,"tint":0.1,"liquid":false}""");
var clock=Package("glass.clock","widget.json","""{"kind":"clock","pack":"glass"}""",[style.Id]);
var music=Package("glass.music","widget.json","""{"kind":"music","pack":"glass"}""",[style.Id]);
var document=new CatalogDocument{Packages=[style,clock,music],Items=[new(){Id="glass-clock",Title="Clock",Kind="clock",Pack="glass",Packages=[clock.Id]},new(){Id="glass-music",Title="Music",Kind="music",Pack="glass",Packages=[music.Id]},new(){Id="pack-glass",Title="Glass",Type="pack",Pack="glass",Includes=["glass-clock","glass-music"]}]};
int fetches=0;
Task<Stream> Fetch(ContentPackage p,CancellationToken ct){ct.ThrowIfCancellationRequested();fetches++;return Task.FromResult<Stream>(new MemoryStream(payloads[p.Id]));}
try{
await Test("clean profile has no installed content",()=>{var s=new ContentStore(Path.Combine(root,"clean"));Check(s.Installed.Count==0);return Task.CompletedTask;});
await Test("pack installs actual files and shares dependencies",async()=>{var s=new ContentStore(Path.Combine(root,"pack"));fetches=0;await s.InstallAsync(document,"pack-glass",Fetch,null,CancellationToken.None);Check(s.IsInstalled("glass-clock")&&s.IsInstalled("glass-music"));Check(fetches==3);Check(File.Exists(s.PackageFile(style.Id,"1.0.0","style.json")));await s.InstallAsync(document,"glass-clock",Fetch,null,CancellationToken.None);Check(fetches==3,"Dependencies downloaded twice");});
await Test("library and uninstall survive without a catalog",async()=>{var path=Path.Combine(root,"offline");var s=new ContentStore(path);await s.InstallAsync(document,"pack-glass",Fetch,null,CancellationToken.None);var local=new ContentStore(path);local.Remove("glass-clock");Check(local.IsInstalled("glass-music"));Check(File.Exists(local.PackageFile(style.Id,"1.0.0","style.json")));local.Remove("glass-music");Check(local.Installed.Count==0);Check(!File.Exists(local.PackageFile(style.Id,"1.0.0","style.json")));});
await Test("bad checksum never registers content",async()=>{var s=new ContentStore(Path.Combine(root,"hash"));var bad=document with{Packages=[style,clock with{Sha256=new string('0',64)},music]};await Reject(()=>s.InstallAsync(bad,"glass-clock",Fetch,null,CancellationToken.None));Check(s.Installed.Count==0);});
await Test("archive traversal cannot escape staging",async()=>{var s=new ContentStore(Path.Combine(root,"traversal"));var hostile=Package("glass.clock","../escape.json","{}");var bad=document with{Packages=[style,hostile,music]};await Reject(()=>s.InstallAsync(bad,"glass-clock",Fetch,null,CancellationToken.None));Check(!File.Exists(Path.Combine(root,"escape.json")));Check(s.Installed.Count==0);});
await Test("cancelled install leaves no partially installed item",async()=>{var s=new ContentStore(Path.Combine(root,"cancel"));using var ct=new CancellationTokenSource();ct.Cancel();await Reject(()=>s.InstallAsync(document,"glass-clock",Fetch,null,ct.Token));Check(s.Installed.Count==0);});
await Test("unknown dependencies are rejected before downloading",async()=>{var s=new ContentStore(Path.Combine(root,"deps"));fetches=0;var bad=document with{Packages=[clock,music]};await Reject(()=>s.InstallAsync(bad,"glass-clock",Fetch,null,CancellationToken.None));Check(fetches==0);});
await Test("catalog rejects dependency cycles",()=>{var a=style with{Dependencies=[clock.Id]};var bad=document with{Packages=[a,clock,music]};try{CatalogRules.Resolve(bad,"glass-clock");throw new Exception("Cycle accepted");}catch(InvalidDataException){}return Task.CompletedTask;});
await Test("monitor placement handles negative coordinates and clipping",()=>{var p=Placement.Center(400,200,new(-1920,0,1920,1040));Check(p.X==-1160&&p.Y==420);return Task.CompletedTask;});
await Test("sleep generation rejects stale completion after reopen",()=>{var policy=new ShellLifetime();var old=policy.Hide(DateTimeOffset.UtcNow);policy.Show();Check(!policy.CanSuspend(old));Check(!policy.ShouldExit(DateTimeOffset.UtcNow.AddMinutes(16)));policy.Hide(DateTimeOffset.UtcNow);Check(policy.ShouldExit(DateTimeOffset.UtcNow.AddMinutes(16)));return Task.CompletedTask;});
await Test("compatible new styles can be published without recompiling the engine",async()=>{var theme=Package("style.midnight","style.json","""{"id":"midnight","name":"Midnight","blur":2,"interactionBlur":3,"tint":0.2,"liquid":true}""");var widget=Package("midnight.clock","widget.json","""{"kind":"clock","pack":"midnight","defaultSize":"S"}""",[theme.Id]);var item=new CatalogItem{Id="midnight-clock",Title="Clock",Pack="midnight",Kind="clock",Packages=[widget.Id]};var next=new CatalogDocument{Items=[item],Packages=[theme,widget]};var store=new ContentStore(Path.Combine(root,"future-style"));await store.InstallAsync(next,item.Id,Fetch,null,CancellationToken.None);WidgetPacks.LoadInstalled(store);Check(WidgetPacks.Get("midnight").Name=="Midnight");var settings=new AppSettings{Widgets=[new(){Pack="midnight"}]};settings.Normalize();Check(settings.Widgets[0].Pack=="midnight");});
await Test("downloaded widget descriptor controls the initial instance size",async()=>{var theme=Package("style.custom","style.json","""{"id":"custom","blur":2,"interactionBlur":2,"tint":0.1,"liquid":false}""");var widget=Package("custom.clock","widget.json","""{"kind":"clock","pack":"custom","defaultSize":"S"}""",[theme.Id]);var item=new CatalogItem{Id="custom-clock",Title="Clock",Pack="custom",Packages=[widget.Id]};var store=new ContentStore(Path.Combine(root,"descriptor"));await store.InstallAsync(new(){Items=[item],Packages=[theme,widget]},item.Id,Fetch,null,CancellationToken.None);var descriptor=store.ReadWidget(item.Id);Check(descriptor.Kind=="clock"&&descriptor.Pack=="custom"&&descriptor.DefaultSize=="S");File.Delete(store.PackageFile(widget.Id,widget.Version,"widget.json"));Check(!store.IsReady(item.Id),"Missing resources still report installed and ready");});
await Test("legacy migration is explicit, local and idempotent",()=>{var store=new ContentStore(Path.Combine(root,"migration"));Check(store.Installed.Count==0);store.ImportLegacy(document);store.ImportLegacy(document);Check(store.Installed.Count==2);Check(store.ReadWidget("glass-clock").Kind=="clock");return Task.CompletedTask;});
await Test("malformed registry documents recover a valid backup",async()=>{
 var directory=Path.Combine(root,"registry-recovery");var repaired=Package("glass.clock","widget.json","""{"kind":"clock","pack":"glass"}""",[style.Id]);document=document with{Packages=[style,repaired,music]};var store=new ContentStore(directory);await store.InstallAsync(document,"glass-clock",Fetch,null,CancellationToken.None);var file=Path.Combine(directory,"installed.json");var valid=File.ReadAllText(file);var malformed=new[]{"null","[null]",valid.Replace("\"packages\": [","\"packages\": [null,")};foreach(var bad in malformed){File.WriteAllText(file+".bak",valid);File.WriteAllText(file,bad);var recovered=new ContentStore(directory);Check(recovered.IsReady("glass-clock"),"Corrupt registry lost its valid backup");}
});
await Test("null catalog document is invalid data",async()=>await Reject(()=>{CatalogRules.Validate(null!);return Task.CompletedTask;}));
await Test("automatic eviction preserves visible windows and drafts",()=>{var life=new ShellLifetime();life.Hide(DateTimeOffset.UtcNow);var evict=typeof(ShellLifetime).GetMethod("CanEvict")??throw new Exception("Automatic eviction has no draft policy");bool Can(bool visible,bool dirty)=>(bool)evict.Invoke(life,[visible,dirty])!;Check(!Can(true,false)&&!Can(false,true)&&Can(false,false));life.Show();Check(!Can(false,false));return Task.CompletedTask;});
await Test("legacy resources are current content rather than an old app version",()=>{var store=new ContentStore(Path.Combine(root,"legacy-version"));store.ImportLegacy(document);Check(store.Installed.All(i=>i.Item.Version=="1.0.0"),"Legacy app version was presented as a content update");return Task.CompletedTask;});
await Test("existing legacy registries upgrade metadata without replacing resources",()=>{var directory=Path.Combine(root,"existing-legacy");var store=new ContentStore(directory);store.ImportLegacy(document);var state=Path.Combine(directory,"installed.json");File.WriteAllText(state,JsonSerializer.Serialize(store.Installed.Select(i=>i with{Item=i.Item with{Version="0.5.2"}}),CatalogJson.Options));var existing=new ContentStore(directory);existing.UpgradeLegacyMetadata();Check(existing.Installed.All(i=>i.Item.Version=="1.0.0"));Check(existing.Installed.All(i=>i.Packages.All(p=>p.Version=="0.5.2")));Check(existing.IsReady("glass-clock"));return Task.CompletedTask;});
await LocalBundleChecks.Run(Test,root);
await Test("management bounds fit small and scaled work areas without hiding lower controls",()=>{foreach(var scale in new[]{1d,1.25,1.5,2})foreach(var work in new[]{new RectD(0,0,1366,688),new RectD(-1920,40,1920,1000),new RectD(0,0,640,360)}){var fit=ShellLayoutRules.Fit(new(-5000,-5000,1180*scale,800*scale),work,scale);Check(fit.X>=work.X&&fit.Y>=work.Y&&fit.X+fit.Width<=work.X+work.Width&&fit.Y+fit.Height<=work.Y+work.Height,"Management escaped its work area");}return Task.CompletedTask;});
}finally{Directory.Delete(root,true);}
Console.WriteLine($"RESULT: {total-failures}/{total} passed");return failures==0?0:1;
